package GeneratedModel {
  private import ScalarValues::*;
  part def Controller {
    in attribute io_5 : Integer;
    attribute servoPhaseMs : Integer := 0;
    attribute servoPhaseIndex : Integer := 0;
    attribute ledPhaseMs : Integer := 0;
    perform action tick {
      first start;
      then assign servoPhaseMs := servoPhaseMs + io_5;
      then assign ledPhaseMs := ledPhaseMs + io_5;
      then if servoPhaseMs >= 2000 {
        first start;
        then assign servoPhaseMs := servoPhaseMs - 2000;
        then assign servoPhaseIndex := servoPhaseIndex + 1;
      }
      then if servoPhaseIndex >= 2 {
        first start;
        then assign servoPhaseIndex := servoPhaseIndex - 2;
      }
      then if ledPhaseMs >= 2000 {
        first start;
        then assign ledPhaseMs := ledPhaseMs - 2000;
      }
    }
    out attribute io_0 : Boolean = (if ledPhaseMs < 1000 ? false else true);
    out attribute io_1 : Boolean = (if ledPhaseMs < 1000 ? true else false);
    out attribute io_2 : Real = (if servoPhaseIndex == 0 ? 0.0 else 180.0);
    out attribute io_3 : Real = (if servoPhaseIndex == 0 ? 90.0 else 0.0);
    out attribute io_4 : Real = (if servoPhaseIndex == 0 ? 180.0 else 90.0);
  }
  part system : Controller;
}
